using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class RayBradbury
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Mars is a mirror, not a crystal.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Science-fiction balances you on the cliff. Fantasy shoves you off.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Disbelief is catching. It rubs off on people.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "All flesh is one: what matter scores.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Mysteries abound where most we seek for answers.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "We clothe ourselves in flame And trade new myths for old.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "People ask me to predict the future, when all I want to do is prevent it. Better yet, build it. Predicting the future is much too easy, anyway. You look at the people around you, the street you stand on, the visible air you breathe, and predict more of the same. To hell with more. I want better.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "My stories run up and bite me in the leg — I respond by writing down everything that goes on during the bite. When I finish, the idea lets go and runs off.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "And what, you ask, does writing teach us? First and foremost, it reminds us that we are alive and that it is gift and a privilege, not a right. We must earn life once it has been awarded us. Life asks for rewards back because it has favored us with animation. So while our art cannot, as we wish it could, save us from wars, privation, envy, greed, old age, or death, it can revitalize us amidst it all.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Every morning I jump out of bed and step on a landmine. The landmine is me. After the explosion, I spend the rest of the day putting the pieces together.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "We never sit anything out. We are cups, constantly and quietly being filled. The trick is knowing how to tip ourselves over and let the beautiful stuff out.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Remember: Plot is no more than footprints left in the snow after your characters have run by on their way to incredible destinations. Plot is observed after the fact rather than before. It cannot precede action. It is the chart that remains when an action is through. That is all Plot ever should be.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Life is like underwear, should be changed twice a day.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Oh God, without them [libraries], what have we? We have no past and we have no future.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "The problem in our country isn't with books being banned, but with people no longer reading. Look at the magazines, the newspapers around us – it's all junk, all trash, tidbits of news. The average TV ad has 120 images a minute. Everything just falls off your mind. … You don't have to burn books to destroy a culture. Just get people to stop reading them.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Go to the edge of the cliff and jump off. Build your wings on the way down.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "My job is to help you fall in love.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Recreate the world in your own image and make it better for your having been here.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "We were put here as witnesses to the miracle of life. We see the stars, and we want them. We are beholden to give back to the universe.... If we make landfall on another star system, we become immortal.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "The gift of life is so precious that we should feel an obligation to pay back the universe for the gift of being alive.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "We are the miracle of force and matter making itself over into imagination and will. Incredible. The Life Force experimenting with forms. You for one. Me for another. The Universe has shouted itself alive. We are one of the shouts.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "A.E. Van Vogt was not strange, he was kind. He gave me advice and helped me along the road to becoming what I wanted to become.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "If you can't read and write you can't think. Your thoughts are dispersed if you don't know how to read and write. You've got to be able to look at your thoughts on paper and discover what a fool you were.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Video games are a waste of time for men with nothing else to do. Real brains don't do that. On occasion? Sure. As relaxation? Great. But not full time— And a lot of people are doing that. And while they're doing that, I'll go ahead and write another novel.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Why would you clone people when you can go to bed with them and make a baby? C'mon, it's stupid.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "I know you've heard it a thousand times before. But it's true — hard work pays off. If you want to be good, you have to practice, practice, practice. If you don't love something, then don't do it.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "I believe the universe created us — we are an audience for miracles. In that sense, I guess, I'm religious.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "A life's work should be based on love.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "There is no future for e-books, because they are not books. E-books smell like burned fuel.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "At the center of religion is love. I love you and I forgive you. I am like you and you are like me. I love all people. I love the world. I love creating. Everything in our life should be based on love.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Joy is the grace we say to God.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "We must move into the universe. Mankind must save itself. We must escape the danger of war and politics. We must become astronauts and go out into the universe and discover the God in ourselves.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "We have too many cellphones. We've got too many Internets. We have got to get rid of those machines. We have too many machines now.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "If you're reluctant to weep, you won't live a full and complete life.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "I am not a science fiction writer. I am a fantasy writer. But the label got put on me and stuck.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Marriage made people old and familiar, while still young.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "We Earth Men have a talent for ruining big beautiful things. The only reason we didn’t set up hot-dog stands in the midst of the Egyptian temple of Karnak is because it was out of the way and served no large commercial purpose.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "I have something to fight for and live for; that makes me a better killer. I’ve got what amounts to a religion, now.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "They began by controlling books of cartoons and then detective books and, of course, films, one way or another, one group or another, political bias, religious prejudice, union pressures; there was always a minority afraid of something, and a great majority afraid of the dark, afraid of the future, afraid of the past, afraid of the present, afraid of themselves and shadows of themselves.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Ignorance is fatal.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "The gods had gone away, and the ritual of the religion continued senselessly, uselessly.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "We think, I’m not a fool today. I’ve learned my lesson. I was a fool yesterday but not this morning. Then tomorrow we find out that, yes, we were a fool today too. I think the only way we can grow and get on in this world is to accept the fact we’re not perfect and live accordingly.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "A book is a loaded gun in the house next door.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "With schools turning out more runners, jumpers, racers, tinkerers, grabbers, snatchers, fliers, and swimmers instead of examiners, critics, knowers, and imaginative creators, the word \"intellectual,\" of course, became the swear word it deserved to be.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "If you don't want a man unhappy politically, don't give him two sides to a question to worry him; give him one. Better yet, give him none.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "We do need knowledge. And perhaps in a thousand years we might pick smaller cliffs to jump off. The books are to remind us what asses and fools we are.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "If you hide your ignorance, no one will hit you, and you'll never learn.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Is it because we're having so much fun at home we've forgotten the world? Is it because we're so rich and the rest of the world's so poor and we just don't care if they are? I've heard rumors; the world is starving, but we're well fed. Is it true, the world works hard and we play? Is that why we're hated so much?", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Montag, you're looking at a coward. I saw the way things were going, a long time back. I said nothing. I'm one of the innocents who could have spoken up and out when no one would listen to the \"guilty,\" but I did not speak and thus became guilty myself.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Stuff your eyes with wonder . . . live as if you'd drop dead in ten seconds. See the world. It's more fantastic than any dream made or paid for in factories.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "But you can't make people listen. They have to come round in their own time, wondering what happened and why the world blew up around them. It can't last.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "There is more than one way to burn a book. And the world is full of people running about with lit matches.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "For it is a mad world and it will get madder if we allow the minorities, be they dwarf or giant, orangutan or dolphin, nuclear-head or water-conversationalist, pro-computerologist or Neo-Luddite, simpleton or sage, to interfere with aesthetics. The real world is the playing ground for each and every group, to make or unmake laws. But the tip of the nose of my book or stories or poems is where their rights end and my territorial imperatives begin, run and rule. If Mormons do not like my plays, let them write their own. If the Irish hate my Dublin stories, let them rent typewriters. If teachers and grammar school editors find my jawbreaker sentences shatter their mushmilk teeth, let them eat stale cake dunked in weak tea of their own ungodly manufacture.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "For, let's face it, digression is the soul of wit. Take the philosophic asides away from Dante, Milton or Hamlet's father's ghost and what stays is dry bones. Laurence Sterne said it once: Digressions, incontestably, are the sunshine, the life, the soul of reading! Take them out and one cold eternal winter would reign in every page. Restore them to the writer - he steps forth like a bridegroom, bids them all-hail, brings in variety and forbids the appetite to fail.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "All floated upon an evening carrousel, with fitful drifts of music wafting up here and there, and voices calling and murmuring from houses that were whitely haunted by television.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "On the whole, the change had done Huxley a share of good. Death made him a handsomer man to deal with. You could talk to him now and he’d have to listen.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "In touch! There’s a slimy phrase. Touch, hell. Gripped! Pawed, rather. Mauled and massaged and pounded by FM voices.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "“And what happened next?” “Silence happened next. God, it was beautiful.”", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "The telephone rang like a spoiled brat.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Then I went in and shot the televisor, that insidious beast, that Medusa, which freezes a billion people to stone every night, staring fixedly, that Siren which called and sang and promised so much and gave, after all, so little, but myself always going back, going back hoping and waiting until—bang!", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "“I believe,” said the first lady, “that our souls are in our hands. For we do everything to the world with our hands. Sometimes I think we don’t use our hands half enough; it’s certain we don’t use our heads.”", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "I’ve done a prideful thing, a thing more sinful than she ever done to me. I took the bottom out of her life.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Hers was simply not a pew-shaped spine. “I just never had a reason ever to sit in a church,” she had told people. She wasn’t vehement about it. She just walked around and lived and moved her hands that were pebble-smooth and pebble-small. Work had polished the nails of those hands with a polish you could never buy in a bottle. The touching of children had made them soft, and the raising of children had made them temperately stern, and the loving of a husband had made them gentle.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Insanity is relative. It depends on who has who locked in what cage.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "THE OCTOBER COUNTRY …that country where it is always turning late in the year. That country where the hills are fog and the rivers are mist; where noons go quickly, dusks and twilights linger, and midnights stay. That country composed in the main of cellars, sub-cellars, coal-bins, closets, attics, and pantries faced away from the sun. That country whose people are autumn people, thinking only autumn thoughts. Whose people passing at night on the empty walks sound like rain…", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "More murders are committed at ninety-two degrees Fahrenheit than any other temperature. Over one hundred, it’s too hot to move. Under ninety, cool enough to survive. But right at ninety-two degrees lies the apex of irritability, everything is itches and hair and sweat and cooked pork. The brain becomes a rat rushing around a red-hot maze. The least thing, a word, a look, a sound, the drop of a hair and—irritable murder.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "“It will only take a minute,” said Uncle Einar’s sweet wife. “I refuse,” he said. “And that takes but a second.”", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Anna said, “Must they have a reason?” “No, not if they’re insane, no,” said Juliet. “In that case no reasons are necessary.”", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "He stood very straight and thought of nothing, or at least thought of thinking nothing.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "All the sadder that Stone, on the brink of his greatest work, turned one day and went off to live in a town we shall call Obscurity by the sea best named The Past.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "The first thing you learn in life is you’re a fool. The last thing you learn in life is you’re the same fool.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Well, I can’t waste a morning arguing with ten-year olds. Needless to say, I was ten myself once and just as silly.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Oh, God, children are children, old women are old women, and nothing in between. They can’t imagine a change they can’t see.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Old men only lie in wait for people to ask them to talk. Then they rattle on like a rusty elevator wheezing up a shaft.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "“No,” said the old man, deep under. “I don’t remember anyone winning anywhere any time. War’s never a winning thing, Charlie. You just lose all the time, and the one who loses last asks for terms. All I remember is a lot of losing and sadness and nothing good but the end of it. The end of it, Charles, that was a winning all to itself, having nothing to do with guns.”", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Any town, New York, Chicago, with its people, becomes improbable with distance. Just as I am improbable here, in Illinois, in a small town by a quiet lake. All of us improbable to one another because we are not present to one another.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Kindness and intelligence are the preoccupations of age. Being cruel and thoughtless is far more fascinating when you’re twenty.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "I’m not afraid. When you live as long as I’ve lived, you lose that, too. I never liked lobster in my life, and mainly because I’d never tried it. On my eightieth birthday I tried it. I can’t say I’m greatly excited over lobster still, but I have no doubt as to its taste now, and I don’t fear it. I dare say death will be a lobster, too, and I can come to terms with it.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "I’ve alway known that the quality of love was the mind, even though the body sometimes refuses this knowledge. The body lives for itself. It lives only to feed and wait for the night. It’s essentially nocturnal. But what of the mind which is born of the sun, William, and must spend thousands of hours of a lifetime awake and aware? Can you balance off the body, that pitiful, selfish thing of night against a whole lifetime of sun and intellect? I don’t know.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "The sun did not rise, it overflowed.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Grandma, he had often wanted to say, Is this where the world began? For surely it had begun in no other than a place like this. The kitchen, without doubt, was the center of creation, all things revolved about it; it was the pediment that sustained the temple.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "And then, quite suddenly, summer was over.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Next year’s going to be even bigger, days will be brighter, nights longer and darker, more people dying, more babies born, and me in the middle of it all.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "They eat the dark, who only stand and breathe.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "God, how we get our fingers in each other’s clay. That’s friendship, each playing the potter to see what shapes we can make of the other.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "And the odd thing in Dad’s voice was the sound truth makes being said. The sound of truth, in a wild roving land of city or plain country lies, will spell any boy.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "And I saw then and there you take a man half-bad and a woman half-bad and put their two good halves together and you got one human all good to share between. That's you, Will, for my money.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "For some, autumn comes early, stays late through life where October follows September and November touches October and then instead of December and Christ's birth, there is no Bethlehem Star, no rejoicing, but September comes again and old October and so on down the years, with no winter, spring, or revivifying summer. For these beings, fall is the ever normal season, the only weather, there be no choice beyond. Where do they come from? The dust. Where do they go? The grave. Does blood stir their veins? No: the night wind. What ticks in their head? The worm. What speaks from their mouth? The toad. What sees from their eye? The snake. What hears with their ear? The abyss between the stars. They sift the human storm for souls, eat flesh of reason, fill tombs with sinners. They frenzy forth. In gusts they beetle-scurry, creep, thread, filter, motion, make all moons sullen, and surely cloud all clear-run waters. The spider-web hears them, trembles—breaks. Such are the autumn people. Beware of them.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "If I was ever a rare fine summer person, that's long ago. Most of us are half-and-half. The August noon in us works to stave off the November chills. We survive by what little Fourth of July wits we've stashed away. But there are times when we're all autumn people.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Good to evil seems evil.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Is Death important? No. Everything that happens before Death is what counts.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "The stars are yours, if you have the head, the hands, and the heart for them.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Night had come on like the closing of a great but gentle eye.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "“War!” The thought stood in Sim’s brain. It shocked and beat at him. These men were running to fight, to kill, over there in those small black cliffs where other people lived. But why? Wasn’t life short enough without fighting and killing?", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Those who live in the best cliffs think they are better than us. That is always man’s attitude when he has power.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Beware, Charlie, old men only lie in wait for people to ask them to talk. Then they rattle on like a rusty elevator wheezing up a shaft.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "“You remember winning, don’t you? A battle won, somewhere?” “No,” said the old man, deep under. “I don’t remember anyone winning anywhere any time. War’s never a winning thing, Charlie. You just lose all the time, and the one who loses last asks for terms. All I remember is a lot of losing and sadness and nothing good but the end of it. The end of it, Charles, that was a winning all to itself, having nothing to do with guns.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "“You really talk,” he said. “Compulsive,” I said.” “You’d make a lousy writer,” he said. “I never knew a writer yet who was a good talker.”", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "I’d hate to have you running hell, the lost souls would never get fried!", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "There’s too much chance for shock. And yet I must tell her the truth. A doctor gets nowhere by lying to his patient.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "You’re a has-been that never was. And you’re going to stay that way, spoiled and narcissistic and small and mean and rotten.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "“You move against my ethics,” said the priest. “A drowning man clutches at anything,” said Nolan, “and ethics may drown with him if that’s what he grabs instead of a life belt.”", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "“Off the mount, Nolan,” said the priest, “and enough of the sermon. What’s your point?”", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "I have hit forty, forty has hit me, like a locomotive.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "He knew that most machines are amoral, neither bad nor good. But by the way you built and shaped them you in turn shaped men, women, and children to be bad or good. A car, for instance, dead brute, unthinking, an unprogrammed bulk, is the greatest destroyer of souls in history. It makes boy-men greedy for power, destruction, and more destruction. It was never intended to do that. But that's how it turned out.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "And though the debate may run another hundred thousand years: What is Love? perhaps we may find that love is the ability of someone to give us back to us. Maybe love is someone seeing and remembering, handing us back to ourselves just a trifle better than we had dared to hope or dream...", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "She knew a thing she should have known all along: that dead people are like wax memory—you take them in your mind, you shape and squeeze them, push a bump here, stretch one out there, pull the body tall, shape and reshape, handle, sculp and finish a man-memory until he’s all out of kilter.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "But all the little inside-people sitting around in her head would rock back in their tiny rockers and cackle and say, “You ain’t foolin’ us none, Grandma.”", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Oh, oh. Here he comes, Moses crossing a Black Sea of bile.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "You know and I know, I am Mr. Nobody from Nowhere, on my way to Eternity with a dead flashlight and no candles.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Some laugh, some cry, some bang the world with fists, some run, but it all sums up the same: they make do. The world swarms with people, each one drowning, but each swimming a different stroke to the far shore.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "The library was like a stone quarry where no rain had fallen in ten thousand years. Way off in that direction: silence. Way off in that direction: hush. It was the time between things finished and things begun. Nobody died here. Nobody was born. The library, and all its books, just were.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "In sum, my contact lenses had made me fifteen years old again. That is: festering, self-crucified bundle of doubt, horror, and absolute imperfection. The worst age in all one’s life had returned to haunt me with its pimpled, bumpy ghost.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "I am a beautiful woman. I have been beautiful all of my life. Which means that from the start people lied because they simply wished to be with me. I grew up surrounded by the untruths of men, women, and children who could not risk my displeasure. When beauty pouts, the world trembles. Have you ever seen a beautiful woman surrounded by men, seen them nodding, nodding? Heard their laughter? Men will laugh at anything a beautiful woman says. Hate themselves, yes, but they will laugh, say no for yes and yes for no.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "And then, the stars came out. It was like that first night of childhood when his father had taken him out beyond the city to a hill where the lights could not diminish the Universe. And there were a thousand, no ten thousand, no ten million billion stars filling the darkness. The stars were manifold and bright, and they did not care. Even then he had known: they do not care. If I breathe or do not breathe, live or die, the eyes that look from all around don’t care.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "It’s big, it’s broad... It’s broad, it’s bright... It fills the sky of All Hallow’s Night... The strangest sight you’ve ever seen. The Monster Tree on Halloween.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "The scythe fell and lay in the grass like a lost smile.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "The days of the Long Cold are done. Because of this one brave, new-thinking man, summer lives in the winter cave.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "O autumn winds that bake and burn And all the world to darkness turn, Now storm and seize and make of me… A swarm of leaves from Autumn’s Tree!", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "“What’s happening, Mr. Moundshroud? Where are we?” Moundshroud struck a flinty finger into fire and held it up. “Why, bless me, boys. It’s the Dark Ages. The longest darkest night ever.”", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Mr. Moundshroud, who are YOU? And Mr. Moundshroud, way up there on the roof, sent his thoughts back: I think you know, boy, I think you know. Will we meet again, Mr. Moundshroud? Many years from now, yes, I’ll come for you. And a last thought from Tom: O Mr. Moundshroud, will we EVER stop being afraid of nights and death? And the thought returned: When you reach the stars, boy, yes, and live there forever, all the fears will go, and Death himself will die.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Oh come, please come, to the Poor Mouth Fair Where the Saints kneel round in their underwear And say out prayers that most need saying For needful sinners who've forgotten praying; And in every alcove and niche you spy The living dead who envy the long since gone Who never wished to die.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "And from above a voice fused half in iron Half in irony gives man a dreadful choice. The role is his, it says, Man makes and loads his own strange dice, They sum at his behest, He dooms himself. He is his own sad jest. Let go? Let be? Why do you ask this gift from Me? When, trussed and bound and nailed, You sacrifice your life, your liberty You hang yourself upon the tenterhook. Pull free!", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "You make to die You are the dead You the assassin of yourself.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "You are the jailer and the jailed, You the impaler and the one that your own Million-fleshed self in dreams by night do hold in thrall and now at noon must kill.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Why have you been so blind? Why have you never seen? The slave and master in one skin Is all your history, no more, no less, Confess! This is what you've been.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Man warring on himself an old tale is; But Man discovering the source of all his sorrow in himself, Finding his left hand and his right Are similar sons, are children fighting In the porchyards of the void?!", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "That so much time was wasted in this pain. Ten thousand years ago he might have let off down To not return again! A dreadful laugh at last escapes his lips; The laughter sets him free. A Fool lives in the Universe! he cries. The Fool is me! And with one final shake of laughter Breaks his bonds. The nails fall skittering to marble floors. And Christ, knelt at the rail, sees miracle As Man steps down in amiable wisdom To give himself what no one else can give: His liberty.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Ten thousand times a million sons of sons move Through one great and towering town Wearing their wits, which means their laughter, As their crown. Set free upon the earth By simple gifts of knowing how mere mirth can cut the bonds And pull the blood spikes out; Their conversation shouts of \"Fool!\"", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "A single face turned upward toward all Time One flesh, one ecstasy, one peace.", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "I am the dreamer and the doer I the hearer and the knower I the giver and the taker I the sword and the wound of sword. If this be true, then let sword fall free from hand. I embrace myself. I laugh until I weep And weep until I smile…", Author = "Ray Bradbury" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ray_Bradbury", Text = "Leave off losings, and take on winnings, Erase all mortal ends, give birth to only new beginnings, In a billion years of morning and a billion years of sleep.", Author = "Ray Bradbury" },
        };
    }
}